import { matches_keyword } from '../../core/search';
import * as store from '../../core/store';
import type { InstructionFolder, InstructionItem } from '../../core/types';
import { copy_text } from '../clipboard';
import { confirm_dialog, prompt_dialog } from '../dialog';
import { el, on } from '../dom';
import { excerpt, relative_time } from '../format';
import { icon } from '../icons';
import { toast } from '../toast';

/**
 * 番外指令备忘录。全局收藏，不分角色。
 * 按作者的要求只做一层文件夹，搜索按标题与正文做简单关键词匹配。
 */

type View = { name: 'list' } | { name: 'editor'; id: string | null };

/** 文件夹筛选。「全部」和「未分类」是两个特殊值。 */
const FILTER_ALL = '__all__';
const FILTER_NONE = '__none__';

export function render_instructions(): HTMLElement {
  let view: View = { name: 'list' };
  let keyword = '';
  let filter: string = FILTER_ALL;
  let folders: InstructionFolder[] = [];
  let items: InstructionItem[] = [];
  let managing = false;

  const page = el('section', { class: 'yj-page' });

  /* ---------------------------------------------------------- 列表 */

  const search_input = el('input', {
    class: 'yj-search__input',
    attrs: { type: 'search', placeholder: '搜索指令标题或内容', enterkeyhint: 'search' },
  });
  const new_button = el('button', {
    class: 'yj-iconbtn yj-search__add',
    html: icon('plus', 19),
    title: '写一条新指令',
    attrs: { type: 'button', 'aria-label': '写一条新指令' },
  });
  const search_row = el('div', { class: 'yj-search' }, [
    el('div', { class: 'yj-search__icon', html: icon('search', 17) }),
    search_input,
    new_button,
  ]);

  const chips_row = el('div', { class: 'yj-chips' });

  const add_folder_button = el('button', {
    class: 'yj-btn yj-btn--ghost yj-folder-bar__btn',
    text: '新建文件夹',
    attrs: { type: 'button' },
  });
  on<Event>(add_folder_button, 'click', () => {
    void add_folder();
  });

  const manage_button = el('button', {
    class: 'yj-btn yj-btn--ghost yj-folder-bar__btn',
    attrs: { type: 'button' },
  });
  on<Event>(manage_button, 'click', () => {
    managing = !managing;
    render();
  });

  const folder_bar = el('div', { class: 'yj-folder-bar' }, [chips_row, add_folder_button, manage_button]);

  const body = el('div', { class: 'yj-ws__body' });

  function empty_state(text: string): HTMLElement {
    return el('div', { class: 'yj-empty' }, [
      el('div', { class: 'yj-empty__mark', html: icon('folder', 30) }),
      el('div', { class: 'yj-empty__text', text }),
    ]);
  }

  function folder_name(id: string | null): string {
    if (id === null) return '未分类';
    return folders.find(folder => folder.id === id)?.name ?? '已删除的文件夹';
  }

  function instruction_row(item: InstructionItem): HTMLElement {
    const copy = el('button', {
      class: 'yj-iconbtn yj-row__action yj-row__copy',
      html: icon('copy', 17),
      title: '复制内容',
      attrs: { type: 'button', 'aria-label': '复制内容' },
    });
    on<Event>(copy, 'click', event => {
      event.stopPropagation();
      void (async () => {
        const ok = await copy_text(item.content);
        toast(ok ? '已复制，去输入框粘贴' : '复制失败');
      })();
    });

    const trash = el('button', {
      class: 'yj-iconbtn yj-row__action yj-row__trash',
      html: icon('trash', 17),
      title: '删除',
      attrs: { type: 'button', 'aria-label': '删除' },
    });
    on<Event>(trash, 'click', event => {
      event.stopPropagation();
      void remove_item(item);
    });

    const row = el('div', { class: 'yj-row yj-row--tappable' }, [
      el('div', { class: 'yj-row__main' }, [
        el('div', { class: 'yj-row__title', text: item.title || '未命名' }),
        el('div', {
          class: 'yj-row__meta',
          text: `${folder_name(item.folder_id)}  ${relative_time(item.updated_at)}  ${excerpt(item.content, 32)}`,
        }),
      ]),
      copy,
      trash,
    ]);
    on<Event>(row, 'click', () => {
      view = { name: 'editor', id: item.id };
      render();
    });
    return row;
  }

  function visible_items(): InstructionItem[] {
    return items.filter(item => {
      if (filter === FILTER_NONE && item.folder_id !== null) return false;
      if (filter !== FILTER_ALL && filter !== FILTER_NONE && item.folder_id !== filter) return false;
      return matches_keyword(keyword, item.title, item.content);
    });
  }

  function render_chips(): void {
    chips_row.replaceChildren();
    const make = (id: string, label: string, removable: string | null): HTMLElement => {
      const chip = el('button', {
        class: `yj-chip${filter === id ? ' is-active' : ''}`,
        attrs: { type: 'button' },
      });
      chip.append(el('span', { text: label }));
      if (removable && managing) {
        const close = el('span', { class: 'yj-chip__x', html: icon('close', 12) });
        on<Event>(close, 'click', event => {
          event.stopPropagation();
          void remove_folder(removable);
        });
        chip.append(close);
      }
      on<Event>(chip, 'click', () => {
        filter = id;
        render();
      });
      return chip;
    };

    chips_row.append(make(FILTER_ALL, '全部', null), make(FILTER_NONE, '未分类', null));
    for (const folder of folders) {
      chips_row.append(make(folder.id, folder.name, folder.id));
    }
  }

  function render_list(): void {
    const visible = visible_items();
    if (!visible.length) {
      body.replaceChildren(
        empty_state(keyword ? '没有匹配的指令。' : '还没有收藏的指令。点右上角的加号，把你自己写的番外指令存进来。'),
      );
      return;
    }
    body.replaceChildren(el('div', { class: 'yj-card' }, visible.map(instruction_row)));
  }

  /* ---------------------------------------------------------- 编辑 */

  function editor_view(id: string | null): HTMLElement {
    const existing = id ? items.find(item => item.id === id) : undefined;
    let folder_id: string | null =
      existing?.folder_id ?? (filter === FILTER_ALL || filter === FILTER_NONE ? null : filter);

    const back = el('button', {
      class: 'yj-iconbtn yj-ws__back',
      html: icon('back', 19),
      title: '返回列表',
      attrs: { type: 'button', 'aria-label': '返回列表' },
    });
    on<Event>(back, 'click', () => {
      view = { name: 'list' };
      render();
    });

    const head = el('section', { class: 'yj-ws__head' }, [
      back,
      el('div', { class: 'yj-ws__title', text: existing ? '编辑指令' : '写一条指令' }),
    ]);

    const title_input = el('input', {
      class: 'yj-input',
      attrs: { type: 'text', placeholder: '标题，例如：让她先开口', value: existing?.title ?? '' },
    });
    const content_area = el('textarea', {
      class: 'yj-textarea',
      attrs: { rows: '10', placeholder: '正文，写你自己要用的指令' },
    });
    content_area.value = existing?.content ?? '';

    const folder_chips = el('div', { class: 'yj-chips' });
    const render_folder_chips = (): void => {
      folder_chips.replaceChildren();
      const make = (value: string | null, label: string): HTMLElement => {
        const chip = el('button', {
          class: `yj-chip${folder_id === value ? ' is-active' : ''}`,
          text: label,
          attrs: { type: 'button' },
        });
        on<Event>(chip, 'click', () => {
          folder_id = value;
          render_folder_chips();
        });
        return chip;
      };
      folder_chips.append(make(null, '未分类'));
      for (const folder of folders) folder_chips.append(make(folder.id, folder.name));
    };
    render_folder_chips();

    const save = el('button', {
      class: 'yj-btn yj-btn--primary',
      text: '保存',
      attrs: { type: 'button' },
    });
    on<Event>(save, 'click', () => {
      void (async () => {
        const title = title_input.value.trim();
        const content = content_area.value.trim();
        if (!title && !content) {
          toast('标题和正文至少写一样');
          return;
        }
        const now = Date.now();
        try {
          await store.put_instruction({
            id: existing?.id ?? store.new_id(),
            folder_id,
            title: title || '未命名',
            content,
            created_at: existing?.created_at ?? now,
            updated_at: now,
          });
          toast('已保存');
          view = { name: 'list' };
          await reload();
        } catch (error) {
          console.warn('[月季管家] 保存指令失败', error);
          toast('保存失败');
        }
      })();
    });

    const actions = el('div', { class: 'yj-detail__actions' }, [save]);

    const sections: HTMLElement[] = [
      head,
      el('div', { class: 'yj-editor__field' }, [el('div', { class: 'yj-editor__label', text: '标题' }), title_input]),
      el('div', { class: 'yj-editor__field' }, [
        el('div', { class: 'yj-editor__label', text: '文件夹' }),
        folder_chips,
      ]),
      el('div', { class: 'yj-editor__field' }, [el('div', { class: 'yj-editor__label', text: '正文' }), content_area]),
    ];

    if (existing) {
      const remove = el('button', {
        class: 'yj-btn yj-btn--danger',
        text: '删除',
        attrs: { type: 'button' },
      });
      on<Event>(remove, 'click', () => {
        void remove_item(existing);
      });
      actions.append(remove);
    }

    sections.push(actions);
    return el('section', { class: 'yj-page' }, sections);
  }

  /* ---------------------------------------------------------- 动作 */

  async function add_folder(): Promise<void> {
    const name = await prompt_dialog({
      title: '新建文件夹',
      confirm_text: '创建',
      input: { placeholder: '例如：开场、日常' },
    });
    if (name === null) return;
    if (!name) {
      toast('文件夹要有个名字');
      return;
    }
    try {
      await store.put_folder({ id: store.new_id(), name, created_at: Date.now() });
      toast('文件夹已创建');
      await reload();
    } catch (error) {
      console.warn('[月季管家] 新建文件夹失败', error);
      toast('创建失败');
    }
  }

  async function remove_folder(id: string): Promise<void> {
    const name = folder_name(id);
    const count = items.filter(item => item.folder_id === id).length;
    const ok = await confirm_dialog({
      title: '确认删除文件夹？',
      message: count
        ? `「${name}」里有 ${count} 条指令，删掉文件夹后它们会回到「未分类」，指令本身不会丢。`
        : `「${name}」是空的，删掉不会影响任何指令。`,
      confirm_text: '删除文件夹',
      danger: true,
    });
    if (!ok) return;
    try {
      await store.delete_folder(id);
      if (filter === id) filter = FILTER_ALL;
      toast('文件夹已删除');
      await reload();
    } catch (error) {
      console.warn('[月季管家] 删除文件夹失败', error);
      toast('删除失败');
    }
  }

  async function remove_item(item: InstructionItem): Promise<void> {
    const ok = await confirm_dialog({
      title: '确认删除？',
      message: `「${item.title || '未命名'}」删掉之后就找不回来了。`,
      confirm_text: '删除',
      danger: true,
    });
    if (!ok) return;
    try {
      await store.delete_instruction(item.id);
      toast('已删除');
      view = { name: 'list' };
      await reload();
    } catch (error) {
      console.warn('[月季管家] 删除指令失败', error);
      toast('删除失败');
    }
  }

  /* ---------------------------------------------------------- 渲染 */

  function render(): void {
    if (view.name === 'editor') {
      page.replaceChildren(editor_view(view.id));
      return;
    }
    manage_button.textContent = managing ? '完成' : '管理';
    search_row.style.display = '';
    folder_bar.style.display = '';
    render_chips();
    render_list();
    page.replaceChildren(search_row, folder_bar, body);
  }

  async function reload(): Promise<void> {
    const [next_folders, next_items] = await Promise.all([store.list_folders(), store.list_instructions()]);
    if (!page.isConnected) return;
    folders = next_folders;
    items = next_items;
    render();
  }

  on<Event>(search_input, 'input', () => {
    keyword = search_input.value;
    render_list();
  });
  on<Event>(new_button, 'click', () => {
    view = { name: 'editor', id: null };
    render();
  });

  render();
  void reload();

  return page;
}
