import * as store from '../../core/store';
import type { CharacterPrefs, ReplaceRule } from '../../core/types';
import { el, on } from '../dom';
import { icon } from '../icons';
import { toast } from '../toast';

/** 文本侧的清洗与替换设置。两件事的生效时机不一样，页面上写清楚了。 */

export interface TextToolsHandlers {
  on_back: () => void;
  on_changed: (prefs: CharacterPrefs) => void;
}

export function render_text_tools(prefs: CharacterPrefs, handlers: TextToolsHandlers): HTMLElement {
  let current: CharacterPrefs = {
    ...prefs,
    clean_tags: [...prefs.clean_tags],
    replace_rules: prefs.replace_rules.map(rule => ({ ...rule })),
  };

  const back = el('button', {
    class: 'yj-iconbtn yj-ws__back',
    html: icon('back', 19),
    title: '返回收藏库',
    attrs: { type: 'button', 'aria-label': '返回收藏库' },
  });
  on<Event>(back, 'click', () => {
    handlers.on_back();
  });

  const head = el('section', { class: 'yj-ws__head' }, [
    back,
    el('div', { class: 'yj-ws__title', text: '文本处理' }),
  ]);

  async function persist(next: CharacterPrefs, message: string): Promise<void> {
    current = next;
    render_all();
    try {
      await store.put_prefs(current);
      handlers.on_changed(current);
      toast(message);
    } catch (error) {
      console.warn('[月季管家] 保存文本处理设置失败', error);
      toast('保存失败');
    }
  }

  /* ---------------------------------------------------------- 清洗标签 */

  const tag_input = el('input', {
    class: 'yj-search__input',
    attrs: { type: 'text', placeholder: '例如 StatusPlaceHolderImpl', enterkeyhint: 'done' },
  });
  const tag_add = el('button', {
    class: 'yj-iconbtn yj-search__add yj-tools__add--tag',
    html: icon('plus', 19),
    title: '添加标签',
    attrs: { type: 'button', 'aria-label': '添加标签' },
  });

  const tag_list = el('div', { class: 'yj-card' });

  function add_tag(): void {
    const value = tag_input.value.trim();
    if (!value) {
      toast('先写一个标签名');
      return;
    }
    if (current.clean_tags.includes(value)) {
      toast('这个标签已经在列表里了');
      return;
    }
    tag_input.value = '';
    void persist(
      { ...current, clean_tags: [...current.clean_tags, value] },
      '已添加清洗标签，之后新收藏的楼层会按它过滤',
    );
  }

  on<Event>(tag_add, 'click', add_tag);
  on<KeyboardEvent>(tag_input, 'keydown', event => {
    if (event.key === 'Enter') add_tag();
  });

  function render_tags(): void {
    tag_list.replaceChildren();
    if (!current.clean_tags.length) {
      tag_list.append(
        el('div', { class: 'yj-empty__text', text: '还没有清洗标签。加一个之后，收藏楼层时会跳过这个标签里的内容。' }),
      );
      tag_list.classList.add('yj-card--plain');
      return;
    }
    tag_list.classList.remove('yj-card--plain');
    for (const tag of current.clean_tags) {
      const trash = el('button', {
        class: 'yj-iconbtn yj-row__action',
        html: icon('trash', 17),
        title: '删除',
        attrs: { type: 'button', 'aria-label': '删除' },
      });
      on<Event>(trash, 'click', () => {
        void persist(
          { ...current, clean_tags: current.clean_tags.filter(item => item !== tag) },
          '已删除清洗标签',
        );
      });
      tag_list.append(
        el('div', { class: 'yj-row' }, [
          el('div', { class: 'yj-row__main' }, [el('div', { class: 'yj-row__title', text: tag })]),
          trash,
        ]),
      );
    }
  }

  /* ---------------------------------------------------------- 替换名词 */

  const from_input = el('input', {
    class: 'yj-search__input',
    attrs: { type: 'text', placeholder: '要找的词', enterkeyhint: 'next' },
  });
  const to_input = el('input', {
    class: 'yj-search__input',
    attrs: { type: 'text', placeholder: '换成什么', enterkeyhint: 'done' },
  });
  const rule_add = el('button', {
    class: 'yj-iconbtn yj-search__add yj-tools__add--rule',
    html: icon('plus', 19),
    title: '添加规则',
    attrs: { type: 'button', 'aria-label': '添加规则' },
  });

  const rule_switch = el('button', {
    class: 'yj-btn yj-btn--ghost',
    attrs: { type: 'button' },
  });
  on<Event>(rule_switch, 'click', () => {
    void persist({ ...current, replace_enabled: !current.replace_enabled }, current.replace_enabled ? '已关闭替换' : '已开启替换');
  });

  const rule_list = el('div', { class: 'yj-card' });

  function add_rule(): void {
    const from = from_input.value.trim();
    const to = to_input.value.trim();
    if (!from) {
      toast('先写要找的词');
      return;
    }
    if (current.replace_rules.some(rule => rule.from === from)) {
      toast('这个词已经有规则了');
      return;
    }
    from_input.value = '';
    to_input.value = '';
    const rules: ReplaceRule[] = [...current.replace_rules, { from, to }];
    void persist({ ...current, replace_rules: rules, replace_enabled: true }, '已添加替换规则');
  }

  on<Event>(rule_add, 'click', add_rule);
  on<KeyboardEvent>(to_input, 'keydown', event => {
    if (event.key === 'Enter') add_rule();
  });

  function render_rules(): void {
    rule_list.replaceChildren();
    if (!current.replace_rules.length) {
      rule_list.classList.add('yj-card--plain');
      rule_list.append(el('div', { class: 'yj-empty__text', text: '还没有替换规则。' }));
      return;
    }
    rule_list.classList.remove('yj-card--plain');
    for (const rule of current.replace_rules) {
      const trash = el('button', {
        class: 'yj-iconbtn yj-row__action',
        html: icon('trash', 17),
        title: '删除',
        attrs: { type: 'button', 'aria-label': '删除' },
      });
      on<Event>(trash, 'click', () => {
        void persist(
          { ...current, replace_rules: current.replace_rules.filter(item => item.from !== rule.from) },
          '已删除替换规则',
        );
      });
      rule_list.append(
        el('div', { class: 'yj-row' }, [
          el('div', { class: 'yj-row__main' }, [
            el('div', { class: 'yj-row__title', text: rule.from }),
            el('div', { class: 'yj-row__meta', text: `换成「${rule.to || '（删掉）'}」` }),
          ]),
          trash,
        ]),
      );
    }
  }

  /* ---------------------------------------------------------- 组装 */

  const container = el('section', { class: 'yj-page' });

  function render_all(): void {
    rule_switch.textContent = current.replace_enabled ? '替换已开启，点此关闭' : '替换已关闭，点此开启';
    render_tags();
    render_rules();

    container.replaceChildren(
      head,
      el('div', { class: 'yj-section' }, [
        el('div', { class: 'yj-section__head' }, [
          el('div', { class: 'yj-section__title', text: '清洗标签' }),
          el('div', { class: 'yj-section__hint', text: '收藏时就丢掉' }),
        ]),
        el('div', { class: 'yj-note', text: '收藏楼层时，这些标签连同里面的内容一起丢掉，只留标签外的正文。用来滤掉状态条、时间组件这类结构。只影响之后新收藏的内容，已经存下来的不会改动。' }),
        el('div', { class: 'yj-search' }, [tag_input, tag_add]),
        tag_list,
      ]),
      el('div', { class: 'yj-section' }, [
        el('div', { class: 'yj-section__head' }, [
          el('div', { class: 'yj-section__title', text: '替换名词' }),
          el('div', { class: 'yj-section__hint', text: '只看不改' }),
        ]),
        el('div', { class: 'yj-note', text: '只在你看收藏的时候显示替换后的文字，存下来的还是原文，聊天本身也不受影响。' }),
        el('div', { class: 'yj-search' }, [from_input, el('div', { class: 'yj-search__icon', html: icon('back', 15) }), to_input, rule_add]),
        rule_list,
        el('div', { class: 'yj-section' }, [rule_switch]),
      ]),
    );
  }

  render_all();
  return container;
}