import { current_character_key, current_character_name } from '../core/character';
import { NO_CHARACTER } from '../core/types';
import { read_context, type TavernContext } from '../tavern/env';
import { el } from './dom';
import { create_panel, type PanelPage } from './panel';
import styles from './shadow.css?raw';
import { start_shot_in_chat } from './shot_in_chat';
import { start_theme } from './theme';
import { create_toolbar } from './toolbar';
import { toast } from './toast';
import { load_auto_open } from './ui_settings';

/** 界面根节点被挂进酒馆主页面的 body，样式全部封在 Shadow DOM 里。 */
export const HOST_ID = 'yueji-guanjia-host';

/** 多久检查一次当前角色卡。酒馆的事件名各版本不一致，轮询最稳。 */
const CHARACTER_POLL_MS = 1200;

export interface AppHandle {
  open_panel: (page?: PanelPage) => void;
  destroy: () => void;
}

export function create_app(context: TavernContext | null): AppHandle {
  const host = el('div', { attrs: { id: HOST_ID } });
  const shadow = host.attachShadow({ mode: 'open' });

  const style = document.createElement('style');
  style.textContent = styles;

  const layer = el('div', { class: 'yj-layer' });
  shadow.append(style, layer);

  /**
   * 用内联样式把根节点的尺寸钉死。
   *
   * 面板用「撑满容器」定位，提示条用「距容器底部多少」定位，都依赖根节点有正确尺寸。
   * 只靠样式表的话，一旦那份样式没生效，根节点就是个空 div，高度为零
   * 表现是工具条照常显示（它用绝对坐标），但面板和提示条全部看不见。
   * 内联样式优先级最高，不受外部样式表影响。
   */
  function apply_host_geometry(): void {
    const width = window.innerWidth || document.documentElement.clientWidth || 0;
    const height = window.innerHeight || document.documentElement.clientHeight || 0;
    host.style.position = 'fixed';
    host.style.top = '0';
    host.style.left = '0';
    host.style.width = `${width}px`;
    host.style.height = `${height}px`;
    host.style.zIndex = '2147483000';
    host.style.pointerEvents = 'none';
  }

  /** 工具条该显示还是该让位。面板开着、或者在挑段落时都要让位。 */
  function sync_toolbar_visibility(): void {
    const hidden = panel.is_open() || document.body.classList.contains('yj-para-mode');
    toolbar.root.style.display = hidden ? 'none' : '';
  }

  const toolbar = create_toolbar({
    on_capture: () => {
      if (document.body.classList.contains('yj-para-mode')) return;
      panel.close();
      void start_shot_in_chat({
        context: read_context(),
        on_enter: sync_toolbar_visibility,
        on_leave: sync_toolbar_visibility,
      });
    },
    on_text: () => {
      const live = read_context();
      const key = current_character_key(live);
      toast('文本收藏在面板里：点花苞  选角色  文本库  加号');
      panel.open({ name: 'workspace', character_key: key, title: current_character_name(live) || '未命名角色' });
    },
    on_home: () => {
      panel.open();
    },
  });

  const panel = create_panel(context, {
    on_visibility: () => {
      sync_toolbar_visibility();
    },
  });

  apply_host_geometry();
  layer.append(panel.backdrop, panel.root);
  document.body.append(host);
  toolbar.mount_into(layer);
  start_theme();

  /* ---------------------------------------------------------- 角色卡监听 */

  let last_key = current_character_key(context);

  function watch_characters(): void {
    const live = read_context();
    const key = current_character_key(live);
    if (key === last_key) return;
    const previous = last_key;
    last_key = key;
    // 首次确定归属时不弹面板，只在真的切了角色之后才自动打开。
    if (previous === '' || key === NO_CHARACTER || !load_auto_open()) return;
    panel.open({
      name: 'workspace',
      character_key: key,
      title: current_character_name(live) || '未命名角色',
    });
  }

  const character_timer = window.setInterval(watch_characters, CHARACTER_POLL_MS);

  function on_viewport_change(): void {
    apply_host_geometry();
  }
  window.addEventListener('resize', on_viewport_change);
  window.addEventListener('orientationchange', on_viewport_change);

  function on_keydown(event: KeyboardEvent): void {
    if (event.key === 'Escape' && panel.is_open()) panel.close();
  }
  document.addEventListener('keydown', on_keydown);

  return {
    open_panel: page => {
      panel.open(page);
    },
    destroy: () => {
      window.clearInterval(character_timer);
      window.removeEventListener('resize', on_viewport_change);
      window.removeEventListener('orientationchange', on_viewport_change);
      document.removeEventListener('keydown', on_keydown);
      toolbar.destroy();
      panel.destroy();
      host.remove();
    },
  };
}
