import { shadow_layer } from './dom';

/** 界面主题。跟随系统时读浏览器的偏好，不额外存状态。 */

export type ThemeMode = 'light' | 'dark' | 'system';

const STORAGE_KEY = 'yueji-guanjia.theme';

let current_mode: ThemeMode = 'system';
let watcher: MediaQueryList | null = null;

export function load_theme(): ThemeMode {
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    return raw === 'light' || raw === 'dark' || raw === 'system' ? raw : 'system';
  } catch (error) {
    console.warn('[月季管家] 读取主题设置失败', error);
    return 'system';
  }
}

function save_theme(mode: ThemeMode): void {
  try {
    window.localStorage.setItem(STORAGE_KEY, mode);
  } catch (error) {
    console.warn('[月季管家] 保存主题设置失败', error);
  }
}

/** 把模式解析成实际生效的主题。 */
export function resolve_theme(mode: ThemeMode): 'light' | 'dark' {
  if (mode !== 'system') return mode;
  try {
    return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
  } catch {
    return 'light';
  }
}

/** 把当前主题刷到内容层上。整棵子树跟着换色，不影响酒馆本身。 */
function apply(): void {
  const layer = shadow_layer();
  if (!layer) return;
  layer.classList.toggle('is-dark', resolve_theme(current_mode) === 'dark');
}

export function get_theme(): ThemeMode {
  return current_mode;
}

export function set_theme(mode: ThemeMode): void {
  current_mode = mode;
  save_theme(mode);
  apply();
}

/** 界面挂载后调用一次：读设置并开始跟随系统。 */
export function start_theme(): void {
  current_mode = load_theme();
  apply();
  if (watcher) return;
  try {
    watcher = window.matchMedia('(prefers-color-scheme: dark)');
    watcher.addEventListener('change', apply);
  } catch (error) {
    console.warn('[月季管家] 无法跟随系统主题', error);
  }
}